const s = $('Settings Loader').first().json;
const CONFIG = {
  COMPANY_NAME: s.business_name,
  APPOINTMENT_TERM: s.appointment_term,
  DEFAULT_TIMEZONE: s.timezone
};

const render = (tpl, vars) => tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => (vars[k] !== undefined && vars[k] !== null) ? vars[k] : '');

const sched = $json;
const lead = $('Normalize Lead').first().json;
const firstName = String(lead.firstName || '').trim();

let smsMessage;
if (!sched.confirmedDate || !sched.confirmedTime) {
  smsMessage = render(s.sms_template_confirmation_failed, { firstName, businessName: CONFIG.COMPANY_NAME, appointmentTerm: CONFIG.APPOINTMENT_TERM });
} else {
  const dm = String(sched.confirmedDate).split('-').map(Number);
  const dt = DateTime.fromObject({ year: dm[0], month: dm[1], day: dm[2] }, { zone: CONFIG.DEFAULT_TIMEZONE });
  const dateDisplay = dt.toFormat('cccc, LLLL d');
  smsMessage = render(s.sms_template_confirmation_success, { firstName, appointmentTerm: CONFIG.APPOINTMENT_TERM, dateDisplay, confirmedTime: sched.confirmedTime });
}

return [{ json: { ...lead, ...sched, schedulingFailed: !sched.confirmedDate, smsMessage } }];
